.valuetech-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e6ecf5;
    background: linear-gradient(165deg, #0c1424 0%, #121d33 55%, #0e1830 100%);
    border-radius: 18px;
}

.valuetech-container * {
    box-sizing: border-box;
}

.valuetech-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #0a1b3a 0%, #15346b 55%, #1f6feb 130%);
    color: #f2f6ff;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 12px 34px rgba(3, 10, 26, 0.55);
    border: 1px solid rgba(80, 130, 220, 0.25);
}

.valuetech-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.valuetech-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #aecbff;
    background: rgba(120, 165, 255, 0.14);
    padding: 5px 14px;
    border-radius: 999px;
}

.valuetech-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #ccdaf2;
}

.valuetech-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #aebfdd;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.valuetech-period-counter #currentDay,
.valuetech-period-counter #maxPeriods {
    font-weight: 800;
    color: #ffffff;
}

.valuetech-round-name {
    background: rgba(95, 140, 240, 0.22);
    color: #cfe0ff;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.valuetech-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ffd2b0;
    background: rgba(214, 110, 50, 0.22);
    padding: 4px 12px;
    border-radius: 999px;
}

.valuetech-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.valuetech-status-card {
    background: #16223d;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #243757;
    box-shadow: 0 4px 16px rgba(3, 10, 26, 0.35);
    border-top: 4px solid #1f6feb;
}

.valuetech-card-value { border-top-color: #2ec28a; }
.valuetech-card-adoption { border-top-color: #4d9bff; }
.valuetech-card-debt { border-top-color: #c79bff; }
.valuetech-card-budget { border-top-color: #f0a93b; }

.valuetech-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8ea2c6;
}

.valuetech-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #ffffff;
}

.valuetech-card-value .valuetech-value { color: #3fe0a0; }
.valuetech-card-adoption .valuetech-value { color: #6cb0ff; }
.valuetech-card-debt .valuetech-value { color: #d3b0ff; }
.valuetech-card-budget .valuetech-value { color: #ffc05f; }

.valuetech-sublabel {
    font-size: 0.75rem;
    color: #8294b5;
    line-height: 1.35;
}

.valuetech-value-strong .valuetech-value { color: #3fe0a0; }
.valuetech-value-weak .valuetech-value { color: #ff6b6b; }

.valuetech-budget-over { border-top-color: #ff6b6b; }
.valuetech-budget-over .valuetech-value { color: #ff6b6b; }

.valuetech-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #0a1530;
    color: #dde8ff;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    border: 1px solid #213657;
}

.valuetech-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #ffc05f;
}

.valuetech-briefing {
    display: flex;
    gap: 14px;
    background: #16223d;
    border-left: 5px solid #1f6feb;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 16px rgba(3, 10, 26, 0.30);
}

.valuetech-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.valuetech-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #ffffff;
    margin-bottom: 6px;
}

.valuetech-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #c3d2ee;
}

.valuetech-briefing-text strong { color: #3fe0a0; }
.valuetech-briefing-text em { color: #ffb088; font-style: italic; }

.valuetech-controls {
    background: #16223d;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #243757;
    box-shadow: 0 4px 16px rgba(3, 10, 26, 0.35);
}

.valuetech-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #ffffff;
    border-bottom: 2px solid #25395a;
    padding-bottom: 8px;
}

.valuetech-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #cdd9f0;
    margin: 14px 0 6px;
}

.valuetech-container select,
.valuetech-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #2c4368;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #0f1c36;
    color: #e6ecf5;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.valuetech-container select:focus,
.valuetech-container input[type="number"]:focus {
    outline: none;
    border-color: #4d9bff;
    box-shadow: 0 0 0 3px rgba(77, 155, 255, 0.20);
}

.valuetech-container select option {
    background-color: #0f1c36;
    color: #e6ecf5;
}

.valuetech-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #1f6feb;
}

.valuetech-range-readout,
.valuetech-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #9fb6e0;
    margin-top: 4px;
}

.valuetech-range-readout span:last-child,
.valuetech-alloc-readout span:nth-child(2) {
    color: #3fe0a0;
    font-weight: 800;
}

.valuetech-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.valuetech-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #11203c;
    border: 1px solid #243a5d;
    border-radius: 9px;
    padding: 8px 12px;
}

.valuetech-alloc-name {
    flex: 1;
    font-size: 0.86rem;
    font-weight: 600;
    color: #c3d2ee;
}

.valuetech-alloc-row input[type="number"] {
    width: 96px;
    flex: 0 0 96px;
}

.valuetech-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.valuetech-container .btn-primary {
    background: linear-gradient(135deg, #1f6feb 0%, #2ec28a 130%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 18px rgba(31, 111, 235, 0.35);
    color: #ffffff;
}

.valuetech-container .btn-primary:hover {
    filter: brightness(1.08);
}

.valuetech-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #2c4368;
    color: #9fb6e0;
    background: transparent;
}

.valuetech-coach {
    background: #0a1530;
    color: #dde8ff;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 20px rgba(3, 10, 26, 0.45);
    border: 1px solid #213657;
}

.valuetech-coach-header {
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #7fb0ff;
    margin-bottom: 8px;
}

.valuetech-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.valuetech-coach-body strong { color: #ffd98a; }
.valuetech-coach-body em { color: #ffb088; font-style: italic; }

.valuetech-history,
.valuetech-chart {
    background: #16223d;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #243757;
    box-shadow: 0 4px 16px rgba(3, 10, 26, 0.35);
}

.valuetech-history h3,
.valuetech-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #ffffff;
}

.valuetech-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #c3d2ee;
}

.valuetech-container table#usfHistoryTable th {
    background: #0f1c36;
    color: #aecbff;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #25395a;
}

.valuetech-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #1e2f4d;
}

.valuetech-container table#usfHistoryTable tr:nth-child(even) td {
    background: #13203a;
}

.valuetech-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .valuetech-container {
        padding: 14px;
    }
    .valuetech-header h1 {
        font-size: 1.7rem;
    }
    .valuetech-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .valuetech-value {
        font-size: 2rem;
    }
    .valuetech-clock {
        margin-left: 0;
    }
    .valuetech-period-counter {
        font-size: 0.88rem;
    }
    .valuetech-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .valuetech-alloc-row {
        flex-wrap: wrap;
    }
    .valuetech-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .valuetech-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* ── v1.1.0 completion debrief (formatCompletionMessage) — append-only, namespaced ── */
.vt-cm {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #dbe6f6;
    background: linear-gradient(165deg, #0c1424 0%, #121d33 100%);
    border: 1px solid #24324d; border-radius: 16px; padding: 22px 24px; margin-top: 8px;
}
.vt-cm-incomplete { font-size: 1rem; color: #8aa0c0; margin: 0; text-align: center; }
.vt-cm-head { display: flex; flex-wrap: wrap; align-items: stretch; gap: 16px; margin-bottom: 18px; }
.vt-cm-score {
    flex: 1 1 200px; background: linear-gradient(135deg, #0a1b3a 0%, #15346b 55%, #1f6feb 130%);
    color: #f4f8ff; border-radius: 14px; padding: 18px 20px; box-shadow: 0 8px 22px rgba(0,0,0,0.35);
}
.vt-cm-score-num { font-size: 2.6rem; font-weight: 800; line-height: 1; letter-spacing: -1px; }
.vt-cm-score-den { font-size: 1.05rem; font-weight: 600; opacity: 0.82; margin-left: 2px; }
.vt-cm-score-lbl { margin-top: 6px; font-size: 0.82rem; text-transform: uppercase; letter-spacing: 0.8px; color: #9fd8ff; font-weight: 700; }
.vt-cm-verdict {
    flex: 2 1 260px; background: #101c33; border: 1px solid #24324d; border-left: 5px solid #2ec28a;
    border-radius: 14px; padding: 18px 20px; display: flex; flex-direction: column; justify-content: center;
}
.vt-cm-verdict-lbl { font-size: 0.78rem; text-transform: uppercase; letter-spacing: 0.9px; color: #8aa0c0; font-weight: 700; }
.vt-cm-verdict-tier { font-size: 1.5rem; font-weight: 800; color: #eaf2ff; margin-top: 4px; letter-spacing: -0.4px; }
.vt-cm-section { margin-top: 16px; }
.vt-cm-section-h { font-size: 0.82rem; text-transform: uppercase; letter-spacing: 0.9px; color: #9fb3d4; font-weight: 700; margin-bottom: 8px; }
.vt-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.vt-cm-chip { display: inline-flex; align-items: center; gap: 6px; font-size: 0.86rem; font-weight: 600; padding: 6px 12px; border-radius: 999px; border: 1px solid transparent; }
.vt-cm-ok { background: rgba(46,194,138,0.16); color: #3fe0a0; border-color: rgba(46,194,138,0.40); }
.vt-cm-no { background: rgba(255,107,107,0.14); color: #ff8a8a; border-color: rgba(255,107,107,0.40); }
.vt-cm-ico { font-weight: 800; }
.vt-cm-kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }
.vt-cm-kpi { background: #101c33; border: 1px solid #24324d; border-top: 4px solid #1f6feb; border-radius: 12px; padding: 12px 14px; text-align: center; }
.vt-cm-kpi:nth-child(1) { border-top-color: #2ec28a; }
.vt-cm-kpi:nth-child(2) { border-top-color: #4d9bff; }
.vt-cm-kpi:nth-child(3) { border-top-color: #c79bff; }
.vt-cm-kpi:nth-child(4) { border-top-color: #f0a93b; }
.vt-cm-kpi-val { font-size: 1.5rem; font-weight: 800; color: #eaf2ff; line-height: 1.1; }
.vt-cm-kpi-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.5px; color: #8aa0c0; font-weight: 700; margin-top: 4px; }
.vt-cm-kpi-sub { font-size: 0.7rem; color: #6f83a3; margin-top: 3px; }
.vt-cm-insights { margin: 0; padding-left: 20px; }
.vt-cm-insights li { font-size: 0.9rem; color: #c3d2ea; line-height: 1.5; margin-bottom: 4px; }
@media (max-width: 640px) { .vt-cm-kpis { grid-template-columns: repeat(2, 1fr); } .vt-cm-head { flex-direction: column; } }

