(function() {
    'use strict';

    class ValueTechAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Value from Tech`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card.
            this.START_VALUE = 12;       // value realized today (~nothing)
            this.START_ADOPTION = 22;    // 22% of last programme used
            this.START_DEBT = 20;        // platform health: 60% of eng time lost to legacy
            this.BUDGET_CAP = 30;        // €30M over two years, in millions
            this.TARGET_VALUE = 65;      // board's bar to keep funding / avoid outsourcing

            // Concept truths.
            this.TRUE_ROOT = `organizational`;
            this.TRUE_DEFINE = `outcomes`;
        }

        // ---- locale-aware money formatter (EN: €30.0M · ES: 30,0 M€) ----
        _money(millions) {
            const lang = (window.mySimulation && window.mySimulation.language) || `en`;
            const v = Math.round(Number(millions) * 10) / 10;
            if (lang === `es`) {
                return v.toFixed(1).replace(`.`, `,`) + ` M€`;
            }
            return `€` + v.toFixed(1) + `M`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    value: this.START_VALUE,
                    adoption: this.START_ADOPTION,
                    debt: this.START_DEBT,
                    budgetUsed: 0,
                    targetMissed: false,
                    technologyBuying: false,
                    valueHistory: [this.START_VALUE],
                    adoptionHistory: [this.START_ADOPTION],
                    debtHistory: [this.START_DEBT],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults = a MIDDLING / classic-reflex mix, NOT the textbook-correct play.
                state.decisions = {
                    root: `budget`,
                    define: `delivered`,
                    honesty: 50,
                    foundation: `mobile`,
                    quickwin: `bigmobile`,
                    sequence: 50,
                    model: `project`,
                    debtSplit: 10,
                    capSplit: 16,
                    changeSplit: 4,
                    core: `buy`,
                    realize: `hope`,
                    regulator: `memo`,
                    board: `systems`,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const root = document.getElementById(`rootInput`);
                const def = document.getElementById(`defineInput`);
                const hon = document.getElementById(`honestyInput`);
                if (root) decisions.root = root.value;
                if (def) decisions.define = def.value;
                if (hon) decisions.honesty = parseInt(hon.value, 10);
                if (!Number.isFinite(decisions.honesty) || decisions.honesty < 0 || decisions.honesty > 100) {
                    warn(`warn_honesty_range`); return false;
                }
            } else if (round === 2) {
                const fo = document.getElementById(`foundationInput`);
                const qw = document.getElementById(`quickwinInput`);
                const seq = document.getElementById(`sequenceInput`);
                if (fo) decisions.foundation = fo.value;
                if (qw) decisions.quickwin = qw.value;
                if (seq) decisions.sequence = parseInt(seq.value, 10);
                if (!Number.isFinite(decisions.sequence) || decisions.sequence < 0 || decisions.sequence > 100) {
                    warn(`warn_sequence_range`); return false;
                }
            } else if (round === 3) {
                const mo = document.getElementById(`modelInput`);
                const co = document.getElementById(`coreInput`);
                if (mo) decisions.model = mo.value;
                if (co) decisions.core = co.value;
                const ds = document.getElementById(`debtSplitInput`);
                const cs = document.getElementById(`capSplitInput`);
                const ch = document.getElementById(`changeSplitInput`);
                if (ds) decisions.debtSplit = parseFloat(ds.value);
                if (cs) decisions.capSplit = parseFloat(cs.value);
                if (ch) decisions.changeSplit = parseFloat(ch.value);
                const parts = [decisions.debtSplit, decisions.capSplit, decisions.changeSplit];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_split_negative`); return false;
                }
                const total = Math.round((decisions.debtSplit + decisions.capSplit + decisions.changeSplit) * 10) / 10;
                if (Math.abs(total - this.BUDGET_CAP) > 0.001) {
                    warn(`warn_split_total`); return false;
                }
            } else if (round === 4) {
                const re = document.getElementById(`realizeInput`);
                const rg = document.getElementById(`regulatorInput`);
                const bo = document.getElementById(`boardInput`);
                const cv = document.getElementById(`convictionInput`);
                if (re) decisions.realize = re.value;
                if (rg) decisions.regulator = rg.value;
                if (bo) decisions.board = bo.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas. value = realized business benefit; adoption = used by the business;
            // debt = platform health (technical-debt paid down); buying = "tech without value" flag.
            let valueDelta = 0, adoptionDelta = 0, debtDelta = 0, buyingDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the value gap as ORGANIZATIONAL, not technical (Common Error 1).
                switch (d.root) {
                    case `organizational`: valueDelta += 10; adoptionDelta += 7; coachKey = `coach_r1_org`; break;
                    case `vendors`: valueDelta -= 5; buyingDelta += 6; coachKey = `coach_r1_vendors`; break;
                    case `budget`: valueDelta -= 3; buyingDelta += 5; coachKey = `coach_r1_budget`; break;
                    case `people`: valueDelta -= 6; adoptionDelta -= 3; coachKey = `coach_r1_people`; break;
                }

                // Define value as measurable OUTCOMES, not technology delivered (Common Error 1).
                switch (d.define) {
                    case `outcomes`: valueDelta += 8; adoptionDelta += 3; if (d.root === this.TRUE_ROOT) coachKey = `coach_r1_sharp`; break;
                    case `delivered`: valueDelta -= 3; buyingDelta += 5; coachKey = (coachKey === `coach_default`) ? `coach_r1_delivered` : coachKey; break;
                    case `features`: valueDelta -= 5; buyingDelta += 6; coachKey = (coachKey === `coach_default`) ? `coach_r1_delivered` : coachKey; break;
                    case `uptime`: valueDelta -= 2; break;
                }

                // Honesty: willingness to confront the organizational gap.
                if (d.honesty >= 60) { valueDelta += 5; adoptionDelta += 2; }
                else if (d.honesty <= 25) { valueDelta -= 5; coachKey = `coach_r1_lowhonesty`; }

                summaryKey = (d.root === this.TRUE_ROOT && d.define === this.TRUE_DEFINE) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Prioritize & sequence: foundation before customer-facing; dependencies matter.
                // R2 is prioritization/sequencing — the €30M is committed in Round 3, so the
                // €-labels here are illustrative initiative costs and do NOT draw down the cap.
                switch (d.foundation) {
                    case `core`: debtDelta += 12; valueDelta += 3; coachKey = `coach_r2_core`; break;
                    case `mobile`: valueDelta += 3; debtDelta -= 5; buyingDelta += 6; coachKey = `coach_r2_mobile`; break;
                    case `ai`: valueDelta += 2; debtDelta -= 5; buyingDelta += 6; coachKey = `coach_r2_ai`; break;
                    case `none`: valueDelta += 1; debtDelta -= 10; buyingDelta += 10; coachKey = `coach_r2_none`; break;
                }

                // The visible Year-1 win that does NOT depend on a frozen mainframe.
                switch (d.quickwin) {
                    case `renewals`: valueDelta += 10; adoptionDelta += 6; if (d.foundation === `core`) coachKey = `coach_r2_seqright`; break;
                    case `broker`: valueDelta += 8; adoptionDelta += 5; break;
                    case `bigmobile`: valueDelta += 2; adoptionDelta -= 3; debtDelta -= 4; buyingDelta += 8; coachKey = `coach_r2_bigmobile`; break;
                    case `none`: valueDelta -= 8; coachKey = `coach_r2_noearly`; break;
                }

                // Dependency discipline (foundation before things that need it).
                if (d.sequence >= 60) { valueDelta += 5; debtDelta += 3; }
                else if (d.sequence <= 25) { valueDelta -= 5; debtDelta -= 3; buyingDelta += 4; coachKey = `coach_r2_nodependency`; }

                summaryKey = (d.foundation === `core` && (d.quickwin === `renewals` || d.quickwin === `broker`)) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Redesign the IT operating model + split the €30M (Common Errors 2,3,4).
                // This is where the entire €30M is committed (validated to total exactly €30.0M).
                spend += (d.debtSplit + d.capSplit + d.changeSplit);

                // Operating model: business ownership of benefit is the value lever.
                switch (d.model) {
                    case `product`: valueDelta += 9; adoptionDelta += 5; coachKey = `coach_r3_product`; break;
                    case `itowns`: valueDelta += 2; adoptionDelta -= 2; coachKey = `coach_r3_itowns`; break;
                    case `project`: valueDelta -= 6; adoptionDelta -= 5; buyingDelta += 6; coachKey = `coach_r3_project`; break;
                    case `outsource`: valueDelta -= 5; adoptionDelta -= 3; debtDelta += 3; coachKey = `coach_r3_outsource`; break;
                }

                // Debt vs capability vs change. Balanced wins: enough debt-paydown to de-risk,
                // enough capability for value, AND real change/adoption money (the missing third).
                debtDelta += Math.round((d.debtSplit - 9) * 1.1);        // debt-paydown raises platform health
                valueDelta += Math.round((d.capSplit - 9) * 0.7);        // capability raises value
                adoptionDelta += Math.round(Math.min(d.changeSplit, 9) * 1.6); // change money drives adoption

                // Capability on sand: lots of capability with little debt-paydown is fragile.
                if (d.capSplit >= 18 && d.debtSplit <= 5) { valueDelta -= 7; debtDelta -= 4; buyingDelta += 6; coachKey = `coach_r3_sand`; }
                // All-debt, no value: starve capability and the board sees nothing.
                else if (d.debtSplit >= 22 && d.capSplit <= 6) { valueDelta -= 8; coachKey = `coach_r3_alldebt`; }
                // Technology = value: no change/adoption money repeats the 22% failure.
                else if (d.changeSplit <= 1) { adoptionDelta -= 7; buyingDelta += 6; coachKey = `coach_r3_nochange`; }
                // Balanced, change-funded split.
                else if (d.debtSplit >= 8 && d.capSplit >= 8 && d.changeSplit >= 5 && d.model === `product`) { valueDelta += 4; adoptionDelta += 3; debtDelta += 2; coachKey = `coach_r3_balanced`; }

                // Build / buy / partner for the core.
                switch (d.core) {
                    case `partner`: debtDelta += 6; valueDelta += 2; break;
                    case `buy`: debtDelta += 3; adoptionDelta -= 2; break;
                    case `build`: debtDelta -= 5; valueDelta -= 3; buyingDelta += 4; coachKey = (coachKey === `coach_default`) ? `coach_r3_build` : coachKey; break;
                }

                summaryKey = (d.model === `product` && d.changeSplit >= 5 && d.debtSplit >= 8 && d.capSplit >= 8) ? `sum_r3_good` : ((d.debtSplit >= 22 || d.capSplit >= 20 || d.changeSplit <= 1) ? `sum_r3_imbalance` : `sum_r3_weak`);
            } else if (round === 4) {
                // Commit & realize value: ownership + metrics, regulator, board case (Common Error 5).
                switch (d.realize) {
                    case `ownersmetrics`: valueDelta += 8; adoptionDelta += 10; coachKey = `coach_r4_owners`; break;
                    case `trainonly`: adoptionDelta += 2; buyingDelta += 4; coachKey = `coach_r4_trainonly`; break;
                    case `itreports`: valueDelta -= 3; buyingDelta += 6; coachKey = `coach_r4_itreports`; break;
                    case `hope`: adoptionDelta -= 6; buyingDelta += 8; coachKey = `coach_r4_hope`; break;
                }

                // The regulator: resilience IS the value case, not a bolt-on memo.
                switch (d.regulator) {
                    case `structural`: valueDelta += 6; debtDelta += 4; if (d.realize === `ownersmetrics`) coachKey = `coach_r4_structural`; break;
                    case `memo`: valueDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r4_memo` : coachKey; break;
                    case `patch`: valueDelta -= 3; debtDelta -= 3; buyingDelta += 4; coachKey = `coach_r4_patch`; break;
                    case `ignore`: valueDelta -= 6; debtDelta -= 3; buyingDelta += 6; coachKey = `coach_r4_ignore`; break;
                }

                // The board's challenge: real value vs another technology spend.
                switch (d.board) {
                    case `evidence`: valueDelta += 7; adoptionDelta += 3; break;
                    case `systems`: valueDelta -= 5; buyingDelta += 8; coachKey = `coach_r4_systems`; break;
                    case `trust`: valueDelta -= 3; buyingDelta += 6; coachKey = `coach_r4_trust`; break;
                }

                // Conviction nudges value.
                valueDelta += Math.round((d.conviction - 60) / 12);

                summaryKey = (d.realize === `ownersmetrics` && d.regulator === `structural` && d.board === `evidence`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting (budget in € millions, committed in Round 3).
            ds.budgetUsed = Math.round((ds.budgetUsed + spend) * 10) / 10;
            // Cap binds: any overspend past €30M is a value penalty (the board will not top up).
            if (ds.budgetUsed > this.BUDGET_CAP + 0.001) {
                valueDelta -= (ds.budgetUsed - this.BUDGET_CAP) * 2;
            }

            // KPIs move on their deltas, clamped 0–100.
            ds.value = Math.max(0, Math.min(100, ds.value + valueDelta));
            ds.adoption = Math.max(0, Math.min(100, ds.adoption + adoptionDelta));
            ds.debt = Math.max(0, Math.min(100, ds.debt + debtDelta));

            // "Buying technology without value": a high accumulating buying signal drags realized
            // value — you can spend €30M and still not realize benefit (the central concept).
            if (buyingDelta >= 6 && ds.adoption < ds.value - 12) ds.technologyBuying = true;
            if (buyingDelta > 0) {
                const drag = Math.min(ds.value, buyingDelta * 0.5);
                ds.value = Math.max(0, ds.value - drag);
            }

            ds.valueHistory.push(Math.round(ds.value));
            ds.adoptionHistory.push(Math.round(ds.adoption));
            ds.debtHistory.push(Math.round(ds.debt));

            if (round === this.ROUNDS.length && ds.value < this.TARGET_VALUE) ds.targetMissed = true;

            // v1.1.0 fix — persist composite where Express grading/reporting reads it
            // (results_utils.php express_resolveDomainScore -> performance.overallScore, then top-level score).
            const composite = this._composite(ds);
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = composite;
            ds.score = composite;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                value: Math.round(ds.value),
                valueDelta: Math.round(valueDelta),
                adoption: Math.round(ds.adoption),
                adoptionDelta: Math.round(adoptionDelta),
                debt: Math.round(ds.debt),
                debtDelta: Math.round(debtDelta),
                budgetUsed: ds.budgetUsed,
                technologyBuying: ds.technologyBuying,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg,
                score: composite,
                overallScore: composite
            };
        }

