            uiManager.bind(`debtDisplay`, `domainState.debt`, (v) => Math.round(v));
            uiManager.bind(`budgetCardDisplay`, `domainState.budgetUsed`, (v) => {
                const card = document.querySelector(`.valuetech-card-budget`);
                if (card) card.classList.toggle(`valuetech-budget-over`, Number(v) > this.BUDGET_CAP + 0.001);
                return this._money(Number(v));
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => this._money(Number(v)) + ` / ` + this._money(this.BUDGET_CAP));

            const self = this;

            // Honesty slider readout.
            const hon = document.getElementById(`honestyInput`);
            const honReadout = document.getElementById(`honestyReadout`);
            if (hon && honReadout) {
                honReadout.textContent = hon.value;
                hon.addEventListener(`input`, function() { honReadout.textContent = hon.value; });
            }

            // Sequence slider readout.
            const seq = document.getElementById(`sequenceInput`);
            const seqReadout = document.getElementById(`sequenceReadout`);
            if (seq && seqReadout) {
                seqReadout.textContent = seq.value;
                seq.addEventListener(`input`, function() { seqReadout.textContent = seq.value; });
            }

            // €30M split live total.
            const splitIds = [`debtSplitInput`, `capSplitInput`, `changeSplitInput`];
            const splitReadout = document.getElementById(`splitReadout`);
            const recompute = function() {
                let total = 0;
                splitIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 10) / 10;
                if (splitReadout) splitReadout.textContent = self._money(total);
                const bar = document.querySelector(`.valuetech-alloc-readout`);
                if (bar) bar.style.color = (Math.abs(total - self.BUDGET_CAP) > 0.001) ? `#ff6b6b` : ``;
            };
            splitIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

