        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.valueHistory.map((_, i) => (i === 0 ? `Start` : `R` + i));
            return {
                valuetechChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.valueHistory },
                        { data: ds.adoptionHistory },
                        { data: ds.debtHistory }
                    ]
                }
