        _composite(ds) {
            // Verbatim v1.0.0 composite (was inline in getPerformanceSummary), extracted so the
            // per-period persisted score and the completion summary are identical by construction.
            const value = Math.round(ds.value);
            const adoption = Math.round(ds.adoption);
            const debt = Math.round(ds.debt);
            return Math.round(value * 0.40 + adoption * 0.35 + debt * 0.25);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const value = Math.round(ds.value);
            const adoption = Math.round(ds.adoption);
            const debt = Math.round(ds.debt);

            const hitTarget = value >= this.TARGET_VALUE;
            const realValue = adoption >= 55 && debt >= 45;
            const buying = ds.technologyBuying || (value < 45 && adoption < 45);
            const composite = this._composite(ds);

            // v1.1.0 fix — tier labels were hardcoded English; now i18n-keyed (localized es).
            let tierKey = `grade_failed`;
            if (hitTarget && realValue && composite >= 68) tierKey = `grade_realized`;
            else if (hitTarget && realValue) tierKey = `grade_credible`;
            else if (hitTarget) tierKey = `grade_thin`;
            else if (value > this.START_VALUE + 18) tierKey = `grade_improving`;
            else if (buying) tierKey = `grade_bought`;
            const performance = window.mySimulation.t(tierKey);

            const insights = [];
            if (hitTarget && realValue) insights.push(window.mySimulation.t(`insight_realized`));
            else if (buying) insights.push(window.mySimulation.t(`insight_buying`));
            else if (hitTarget) insights.push(window.mySimulation.t(`insight_thin`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (debt < 45) insights.push(window.mySimulation.t(`insight_sand`));
            if (adoption < 45) insights.push(window.mySimulation.t(`insight_adoption`));
            if (!hitTarget) insights.push(window.mySimulation.t(`insight_outsource`));
            if (hitTarget && realValue && debt >= 55) insights.push(window.mySimulation.t(`insight_durable`));

            return {
                value: value,
                adoption: adoption,
                debt: debt,
                hitTarget: hitTarget,
                buying: buying,
                composite: composite,
                performance: performance,
                performanceKey: tierKey,
                budgetUsed: ds.budgetUsed,
                onBudget: ds.budgetUsed <= this.BUDGET_CAP,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            if (!summary || summary.composite == null) {
                return `<div class="vt-cm"><p class="vt-cm-incomplete">` + t(`cm_incomplete`) + `</p></div>`;
            }
            const s = summary;
            const chip = (ok, label) => `<span class="vt-cm-chip ` + (ok ? `vt-cm-ok` : `vt-cm-no`) + `">` +
                `<span class="vt-cm-ico">` + (ok ? `\u2713` : `\u2715`) + `</span>` + label + ` \u00b7 ` +
                (ok ? t(`cm_met`) : t(`cm_missed`)) + `</span>`;
            const kpi = (label, val, sub) => `<div class="vt-cm-kpi"><div class="vt-cm-kpi-val">` + val +
                `</div><div class="vt-cm-kpi-lbl">` + label + `</div>` +
                (sub ? `<div class="vt-cm-kpi-sub">` + sub + `</div>` : ``) + `</div>`;
            const vOk = s.value >= this.TARGET_VALUE, aOk = s.adoption >= 55, dOk = s.debt >= 45, budOk = !!s.onBudget;
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `` +
`<div class="vt-cm">` +
  `<div class="vt-cm-head">` +
    `<div class="vt-cm-score"><div class="vt-cm-score-num">` + Math.round(s.composite) +
       `<span class="vt-cm-score-den">/100</span></div>` +
       `<div class="vt-cm-score-lbl">` + t(`cm_score`) + `</div></div>` +
    `<div class="vt-cm-verdict"><div class="vt-cm-verdict-lbl">` + t(`cm_verdict`) + `</div>` +
       `<div class="vt-cm-verdict-tier">` + s.performance + `</div></div>` +
  `</div>` +
  `<div class="vt-cm-section"><div class="vt-cm-section-h">` + t(`cm_targets`) + `</div>` +
    `<div class="vt-cm-chips">` + chip(vOk, t(`cm_t_value`)) + chip(aOk, t(`cm_t_adopt`)) +
      chip(dOk, t(`cm_t_debt`)) + chip(budOk, t(`cm_t_budget`)) + `</div></div>` +
  `<div class="vt-cm-section"><div class="vt-cm-section-h">` + t(`cm_kpis`) + `</div>` +
    `<div class="vt-cm-kpis">` +
      kpi(t(`value_label`), Math.round(s.value), t(`cm_sub_value`)) +
      kpi(t(`adoption_label`), Math.round(s.adoption) + `%`, t(`cm_sub_adopt`)) +
      kpi(t(`debt_label`), Math.round(s.debt), t(`cm_sub_debt`)) +
      kpi(t(`cm_kpi_budget`), this._money(s.budgetUsed), t(`cm_sub_budget`)) +
    `</div></div>` +
  (insights ? `<div class="vt-cm-section"><div class="vt-cm-section-h">` + t(`cm_insights`) +
      `</div><ul class="vt-cm-insights">` + insights + `</ul></div>` : ``) +
`</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.technologyBuying) return window.mySimulation.t(`hint_buying`);
            if (ds.debt < 35 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_sand`);
            if (ds.adoption < 35) return window.mySimulation.t(`hint_adoption`);
            if (state.currentPeriod >= 3 && ds.value < 40) return window.mySimulation.t(`hint_behind`);
            if (ds.value >= this.TARGET_VALUE && ds.adoption >= 55 && ds.debt >= 45) return window.mySimulation.t(`hint_strong`);
            return null;
        }

